# Check if output[r][c] = input[r % 13][c % 13]
def tiling_transform(input_grid, output_grid):
    """Check if output is an infinite tiling of input wrapped to output size"""
    for r in range(len(output_grid)):
        for c in range(len(output_grid[0])):
            val_out = output_grid[r][c]
            val_in = input_grid[r % len(input_grid)][c % len(input_grid[0])]
            if val_out != val_in:
                # Find first mismatch
                return False, (r, c), val_out, val_in
    return True, None, None, None

