# Try rotating input 180 degrees and checking

def rotate_180(grid):
    rows = list(reversed(grid))
    return [list(reversed(row)) for row in rows]

def rotate_90(grid):
    return [list(col)[::-1] for col in zip(*grid)]

def rotate_270(grid):
    return [list(col) for col in zip(*grid[::-1])]

